from pathlib import Path
import html,re,json,hashlib
p=Path(__file__).resolve().parents[1]
files=sorted((p/'policies').glob('*.md'))
documents=[{'path':'policies/'+f.name,'version':'2026-10-23-draft.1','sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'text':f.read_text()} for f in files]
canonical=json.dumps(documents,ensure_ascii=False,sort_keys=True,separators=(',',':'))
manifest={'status':'DRAFT_NOT_EFFECTIVE','effectiveDate':None,'version':'2026-10-23-draft.1','bundleHash':hashlib.sha256(canonical.encode()).hexdigest(),'canonicalization':'UTF-8 JSON documents array: sorted keys, no whitespace, Unicode unescaped; hash includes exact document text','documents':documents}
(p/'legal-bundle.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
def inline(s):
 s=html.escape(s)
 s=re.sub(r'\[([^]]+)\]\(([^)]+)\)',lambda m:f'<a href="#{Path(m[2]).stem}">{m[1]}</a>' if m[2].endswith('.md') else m[0],s)
 return re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',s)
def render(t):
 out=[]
 for block in t.split('\n\n'):
  if block.startswith('# '):out.append('<h2>'+inline(block[2:])+'</h2>')
  elif block.startswith('## '):out.append('<h3>'+inline(block[3:])+'</h3>')
  elif block.startswith('> '):out.append('<aside class="draft">'+inline(block.replace('> ','').replace('\n>','\n'))+'</aside>')
  elif re.match(r'^1\. ',block):out.append('<ol>'+''.join('<li>'+inline(re.sub(r'^\d+\. ','',x))+'</li>' for x in block.splitlines())+'</ol>')
  else:out.append('<p>'+inline(block)+'</p>')
 return '\n'.join(out)
nav=''.join(f'<a href="#{f.stem}">{html.escape(f.read_text().splitlines()[0][2:])}</a>' for f in files)
articles=''.join(f'<article id="{f.stem}">{render(f.read_text())}<a href="#top">Back to policy list ↑</a></article>' for f in files)
template='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Gold On The Spot — Attorney Review</title><style>
:root{color-scheme:light;--navy:#0a2437;--gold:#bd8d2c;--ink:#203342}*{box-sizing:border-box}body{margin:0;font:16px/1.65 system-ui,sans-serif;color:var(--ink);background:#f5f3ed}header{background:var(--navy);color:white;padding:24px max(20px,calc((100vw - 1160px)/2));border-bottom:4px solid var(--gold)}header b{font:700 24px Georgia,serif}header p{margin:8px 0 0;font-size:14px;color:#ecd494}main{max-width:1160px;margin:auto;padding:28px 24px}h1,h2,h3{font-family:Georgia,serif;line-height:1.25;color:var(--navy)}h1{font-size:34px;margin:0 0 14px}h2{font-size:28px}h3{font-size:20px;margin-top:28px}a{color:#174d6d;text-underline-offset:3px}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid var(--gold);outline-offset:3px}.intro{max-width:850px}.controls{display:flex;gap:16px;align-items:center;margin:20px 0}.search{flex:1}input[type=search]{display:block;width:100%;padding:12px;border:1px solid #82919b;font:inherit;background:white}button{font:600 15px system-ui;padding:13px 18px;border:1px solid var(--navy);background:var(--navy);color:white;cursor:pointer}button:disabled{background:#e0e4e6;color:#45525c;border-color:#a2adb5;cursor:not-allowed}nav{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 24px;margin:14px 0 28px}nav a{padding:9px 0;border-bottom:1px solid #d6d5cf;font-size:14px;text-decoration:none}article{background:white;border-top:3px solid var(--gold);padding:24px 34px;margin:24px 0;scroll-margin-top:12px;overflow-wrap:anywhere}.draft{padding:16px;background:#f8f3e4;border-left:3px solid var(--gold);font-size:13px;white-space:pre-line}li{margin:10px 0}.demo{background:#e7edf0;padding:22px;margin-top:25px}.demo label{display:flex;gap:12px;align-items:flex-start}.demo input{margin-top:7px;width:18px;height:18px;flex:none}.note{font-size:14px}footer{padding:24px;border-top:1px solid #ccc;text-align:center}p{margin:14px 0}[hidden]{display:none!important}@media(max-width:600px){main{padding:20px 14px}h1{font-size:28px}article{padding:20px 18px}h2{font-size:24px}nav{grid-template-columns:1fr}.controls{align-items:flex-end;gap:8px}.controls button{padding:13px 10px}.demo{padding:16px}}@media print{body{background:white;font-size:10pt}header,nav,.controls,.demo,footer,.intro,#matches{display:none}main{padding:0}article{break-before:page;border:0;margin:0;padding:0}article[hidden]{display:block!important}article>a{display:none}h2{font-size:20pt}h3{break-after:avoid}p,li{orphans:3;widows:3}.draft{font-size:9pt}}
</style></head><body><header id="top"><b>Gold On The Spot</b><p>PRIVATE REVIEW COPY · NOT PUBLISHED · NO AGREEMENT IN EFFECT</p></header><main><section class="intro"><h1>Legal &amp; customer protection center</h1><p>Sixteen proposed policies for attorney and owner review. Version <strong>2026-10-23-draft.1</strong> · Prepared October 23, 2026 · Effective date not assigned.</p><p class="note">Unverified entity and address fields are intentional. This preview cannot accept an order, collect a signature, take payment or change the live website. The two-business-day wire deadline, liability limits and arbitration require approval.</p></section><div class="controls"><label class="search">Find policy text<input id="search" type="search" placeholder="Search deadlines, refunds, privacy…"></label><button id="print" type="button">Print drafts</button></div><p id="matches" role="status" aria-live="polite">16 policies</p><nav aria-label="Legal policies">NAV</nav><section class="demo" aria-labelledby="demo-title"><h2 id="demo-title">Checkout presentation — demonstration only</h2><p>Read the <a href="#01-terms-of-service">Terms</a>, <a href="#02-customer-purchase-agreement">Purchase Agreement</a>, <a href="#05-market-loss-price-lock">Market Loss Policy</a> and <a href="#04-refunds-returns-cancellations">Refund Policy</a>.</p><label><input id="assent" type="checkbox"><span>I agree to the linked purchase terms. I understand my submission is an offer; only definitive Company acceptance creates a binding agreement. After acceptance, payment is due by the disclosed deadline and an unjustified default may result in documented, legally recoverable losses. Mandatory consumer rights remain protected.</span></label><p class="note">This abbreviated layout is a visual demonstration; the exact proposed acknowledgment is versioned in implementation/contracts.mjs. Wire deadline acknowledgment and optional marketing require separate controls in the future integrated checkout.</p><p id="demo-status" role="status">No consent is collected or saved.</p><button disabled>Order submission unavailable in review copy</button></section>ARTICLES</main><footer>Attorney review required. No fees, arbitration, payments or public checkout changes activated.</footer><script>
const input=document.querySelector('#search'), articles=[...document.querySelectorAll('article')],links=[...document.querySelectorAll('nav a')];
input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase();let n=0;articles.forEach((a,i)=>{const show=!q||a.textContent.toLowerCase().includes(q);a.hidden=!show;links[i].hidden=!show;if(show)n++});document.querySelector('#matches').textContent=n+' policies match';});
document.querySelector('#print').addEventListener('click',()=>window.print());
document.querySelector('#assent').addEventListener('change',()=>{document.querySelector('#demo-status').textContent='Demonstration only. No consent is collected or saved.';});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a){const target=document.getElementById(a.getAttribute('href').slice(1));if(target?.hidden){input.value='';input.dispatchEvent(new Event('input'));}}});
</script></body></html>'''
(p/'review.html').write_text(template.replace('NAV',nav).replace('ARTICLES',articles))
print('Created review.html and immutable-text manifest:',manifest['bundleHash'])
